package com.intland.codebeamer.wiki.plugins.streamreuse;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.HttpServletRequest; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import org.springframework.stereotype.Component;
@Component
public class CodebeamerV3StreamMetadataClient implements StreamMetadataClient {
 private final ObjectMapper mapper=new ObjectMapper();
 public StreamReuseModels.EntityInfo findStream(HttpServletRequest r,int id){JsonNode n=get(r,"/api/v3/streams/"+id);return ref(n,id);}
 public StreamReuseModels.EntityInfo resolveTrackerVariant(HttpServletRequest r,int streamId,int trackerId){JsonNode n=get(r,"/api/v3/streams/"+streamId+"/trackers/"+trackerId+"/variant");return ref(n,null);}
 private StreamReuseModels.EntityInfo ref(JsonNode n,Integer fallback){Integer id=n.hasNonNull("id")?n.get("id").asInt():fallback;String name=n.hasNonNull("name")?n.get("name").asText():"#"+id;if(id==null)throw new IllegalStateException("Stream API response did not contain an id");return new StreamReuseModels.EntityInfo(id,name);}
 private JsonNode get(HttpServletRequest request,String path){HttpURLConnection c=null;try{String base=request.getScheme()+"://"+request.getServerName()+((request.getServerPort()==80||request.getServerPort()==443)?"":":"+request.getServerPort())+request.getContextPath();c=(HttpURLConnection)new URL(base+path).openConnection();c.setRequestMethod("GET");c.setConnectTimeout(5000);c.setReadTimeout(15000);String cookie=request.getHeader("Cookie");if(cookie!=null)c.setRequestProperty("Cookie",cookie);c.setRequestProperty("Accept","application/json");int status=c.getResponseCode();InputStream in=status>=200&&status<300?c.getInputStream():c.getErrorStream();String body=read(in);if(status<200||status>=300)throw new IllegalStateException("GET "+path+" returned HTTP "+status+": "+body);return mapper.readTree(body);}catch(Exception e){throw new IllegalStateException("Unable to query Codebeamer Stream API for "+path,e);}finally{if(c!=null)c.disconnect();}}
 private String read(InputStream in)throws IOException{if(in==null)return"";try(BufferedReader b=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){StringBuilder s=new StringBuilder();String l;while((l=b.readLine())!=null)s.append(l);return s.toString();}}
}
